import { useEffect } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { createSupabaseBrowserClient, isLiveSupabase } from '@/lib/supabase/client';
import type { MonitoredSiteWithLatestCheck } from '@pingwatch/shared';

export function useRealtimeStatus() {
  const queryClient = useQueryClient();

  useEffect(() => {
    if (!isLiveSupabase()) {
      return;
    }

    const supabase = createSupabaseBrowserClient();

    const channel = supabase
      .channel('monitored-sites-realtime')
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'monitored_sites',
        },
        (payload) => {
          const updatedSite = payload.new as MonitoredSiteWithLatestCheck;
          // Invalidate and update sites cache instantly
          queryClient.setQueryData<MonitoredSiteWithLatestCheck[]>(['sites'], (oldSites) => {
            if (!oldSites) return [updatedSite];
            return oldSites.map((s) => (s.id === updatedSite.id ? { ...s, ...updatedSite } : s));
          });
          queryClient.invalidateQueries({ queryKey: ['site-checks', updatedSite.id] });
          queryClient.invalidateQueries({ queryKey: ['site-incidents', updatedSite.id] });
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'incidents',
        },
        () => {
          queryClient.invalidateQueries({ queryKey: ['site-incidents'] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [queryClient]);
}
